// Текст комментария для случая, когда писатель не вызывался.
//
// Зачем. Раньше нода skip-writer ставила одну заглушку «Отказ правомерен» на все случаи.
// За 60 дней так вышло 44 разбора, и у 29 из них вердикт был «недостаточно_данных» —
// то есть РОП читал в карточке неправду. Хуже того, при сбое судьи (пустой ответ, нет
// обязательных полей) в skip-writer уходил результат вообще без вердикта, и в карточке
// появлялось «Отказ правомерен» на сделке, которую никто не оценивал.
//
// Правило: слово «правомерен» появляется только при вердикте «правомерен». Во всех остальных
// случаях текст честно говорит, что разбора нет и почему.
//
// Источник правок — этот файл. Тот же код вставлен в ноду skip-writer воркфлоу
// «Отказ: Анализ сделки». Моки: tests/skip-writer/run.js

// Сколько символов пояснения берём из exact_reason судьи.
var SKIPW_REASON_LIMIT = 220;

// Первое предложение пояснения судьи: в нём обычно и сказано, чего не хватило.
function skipwFirstSentence(text, limit) {
  if (!text) return '';
  var t = String(text).replace(/\s+/g, ' ').trim();
  var dot = t.search(/[.!?](\s|$)/);
  if (dot > 20) t = t.slice(0, dot + 1);
  if (t.length > limit) t = t.slice(0, limit).replace(/\s+\S*$/, '') + '…';
  return t;
}

// judge — разобранный ответ судьи (может быть пустым объектом или undefined).
function buildSkipWriterComment(judge) {
  var j = judge || {};
  var verdict = j.verdict || null;
  var short = (j.verdict_reason_short || '').trim();
  var exact = skipwFirstSentence(j.exact_reason, SKIPW_REASON_LIMIT);

  if (verdict === 'недостаточно_данных') {
    // Чего именно не хватило — из пояснения судьи, а при его отсутствии общей фразой.
    var why = exact || short || 'в материалах сделки нет содержательных диалогов с клиентом';
    return 'Недостаточно данных для оценки: ' + why;
  }

  if (verdict === 'правомерен') {
    return short ? 'Отказ правомерен: ' + short : 'Отказ правомерен.';
  }

  if (verdict === 'неправомерен') {
    // Сюда попадать не должно: такой вердикт идёт к писателю. Но если попал — без слова
    // «правомерен» и без выдумывания разбора.
    return short
      ? 'Отказ неправомерен: ' + short + '. Подробный разбор не сформирован.'
      : 'Отказ неправомерен. Подробный разбор не сформирован.';
  }

  // Вердикта нет вообще — значит судья не отработал. Ничего не утверждаем.
  return 'Разбор не сформирован: вердикт не получен.';
}
